using System.Reflection;

var asmPath = Path.Combine(
    Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
    ".nuget/packages/microsoft.agents.ai/1.10.0/lib/net10.0/Microsoft.Agents.AI.dll");
var absPath = Path.Combine(
    Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
    ".nuget/packages/microsoft.agents.ai.abstractions/1.10.0/lib/net10.0/Microsoft.Agents.AI.Abstractions.dll");

var abs = Assembly.LoadFrom(absPath);
var asm = Assembly.LoadFrom(asmPath);

foreach (var a in new[] { abs, asm })
{
    Console.WriteLine($"\n=== {a.GetName().Name} ===");
    foreach (var t in a.GetExportedTypes().OrderBy(t => t.FullName))
    {
        Console.WriteLine($"\n{t.FullName} : {string.Join(", ", t.GetInterfaces().Select(i => i.Name))}");
        foreach (var c in t.GetConstructors())
            Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
        foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
            Console.WriteLine($"  prop {p.Name}: {p.PropertyType.Name}");
        foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
            Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    }
}
EOF

