cat > /tmp/reflect-proj/Program.cs << 'CSEOF'
using System.Reflection;

// Find all assemblies in the packages
var nugetDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/microsoft.agents.ai/1.10.0/lib/net10.0");
var absDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".nuget/packages/microsoft.agents.ai.abstractions/1.10.0/lib/net10.0");

// Load using MetadataLoadContext to avoid dependency issues
var resolver = new PathAssemblyResolver(new[] {
    Path.Combine(nugetDir, "Microsoft.Agents.AI.dll"),
    Path.Combine(absDir, "Microsoft.Agents.AI.Abstractions.dll"),
    typeof(object).Assembly.Location,
    Path.Combine(Path.GetDirectoryName(typeof(object).Assembly.Location)!, "System.Runtime.dll"),
});

using var mlc = new MetadataLoadContext(resolver);
foreach (var dllPath in new[] { 
    Path.Combine(absDir, "Microsoft.Agents.AI.Abstractions.dll"),
    Path.Combine(nugetDir, "Microsoft.Agents.AI.dll") 
})
{
    var asm = mlc.LoadFromAssemblyPath(dllPath);
    Console.WriteLine($"\n=== {asm.GetName().Name} ===");
    foreach (var t in asm.GetTypes().Where(t => t.IsPublic).OrderBy(t => t.FullName))
    {
        Console.WriteLine($"\n  {t.FullName}");
        foreach (var c in t.GetConstructors())
            Console.WriteLine($"    ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
        foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
