using System.ComponentModel;
using System.Net;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Chat client (MEAI abstraction over OpenAI)
// ---------------------------------------------------------------------------
IChatClient chatClient = new Microsoft.Extensions.AI.OpenAIChatClient(
    new OpenAI.Chat.ChatClient(modelId, apiKey));

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new ResearchNotebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchAsync,       "web_search",  "Search the web for information on a query. Returns a list of result snippets."),
    AIFunctionFactory.Create(notebook.AddNote,      "add_note",    "Save a research note with a title and body for later reference."),
    AIFunctionFactory.Create(notebook.GetNotes,     "get_notes",   "Retrieve all research notes saved so far."),
    AIFunctionFactory.Create(notebook.ClearNotes,   "clear_notes", "Clear all saved research notes."),
};

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When the user gives you a topic:
        1. Search the web for relevant information using the web_search tool (make multiple searches with different queries to get broad coverage).
        2. Save key findings as notes using the add_note tool.
        3. After gathering enough information, retrieve your notes with get_notes and write a concise, well-structured summary of your findings.
        Always cite the sources you found. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════════╗");
Console.WriteLine("║         Research Agent (type 'exit' to quit) ║");
Console.WriteLine("╚══════════════════════════════════════════════╝");
Console.WriteLine();

var session = await agent.CreateSessionAsync();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("exit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    notebook.ClearNotes();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching…");
    Console.ResetColor();

    try
    {
        await foreach (var update in agent.RunStreamingAsync(input, session))
        {
            if (!string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");

// ---------------------------------------------------------------------------
// Web search tool implementation (uses Bing search scraping as a fallback)
// ---------------------------------------------------------------------------
static async Task<string> WebSearchAsync(
    [Description("The search query to look up on the web")] string query,
    [Description("Maximum number of results to return")] int maxResults = 5)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    try
    {
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
        var html = await http.GetStringAsync(url);

        var results = ParseSearchResults(html, maxResults);
        return results.Count > 0
            ? string.Join("\n\n", results.Select((r, i) => $"[{i + 1}] {r}"))
            : $"No results found for: {query}";
    }
    catch (Exception ex)
    {
        return $"Search failed ({ex.Message}). Please try a different query.";
    }
}

static List<string> ParseSearchResults(string html, int max)
{
    var results = new List<string>();
    var snippetTag = "class=\"result__snippet";
    var titleTag = "class=\"result__a";
    var urlTag = "class=\"result__url";
    var pos = 0;

    while (results.Count < max && pos < html.Length)
    {
        var titleIdx = html.IndexOf(titleTag, pos, StringComparison.Ordinal);
        if (titleIdx < 0) break;

        var title = ExtractTagContent(html, titleIdx);
        var urlText = "";
        var snippet = "";

        var urlIdx = html.IndexOf(urlTag, titleIdx, StringComparison.Ordinal);
        if (urlIdx >= 0) urlText = ExtractTagContent(html, urlIdx).Trim();

        var snippetIdx = html.IndexOf(snippetTag, titleIdx, StringComparison.Ordinal);
        if (snippetIdx >= 0) snippet = ExtractTagContent(html, snippetIdx);

        pos = snippetIdx >= 0 ? snippetIdx + 1 : titleIdx + 1;

        if (!string.IsNullOrWhiteSpace(title))
        {
            results.Add($"{StripHtml(title)}\n  URL: {StripHtml(urlText)}\n  {StripHtml(snippet)}");
        }
    }

    return results;
}

static string ExtractTagContent(string html, int attrPos)
{
    var gt = html.IndexOf('>', attrPos);
    if (gt < 0) return "";
    var closeTag = html.IndexOf('<', gt + 1);
    if (closeTag < 0) return html[(gt + 1)..];
    return html[(gt + 1)..closeTag];
}

static string StripHtml(string text) =>
    System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", "").Trim();

// ---------------------------------------------------------------------------
// Research notebook (note-taking tool)
// ---------------------------------------------------------------------------
sealed class ResearchNotebook
{
    private readonly List<(string Title, string Body)> _notes = [];

    [Description("Save a research note")]
    public string AddNote(
        [Description("Short title for the note")] string title,
        [Description("Body content of the note")] string body)
    {
        _notes.Add((title, body));
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieve all saved research notes")]
    public string GetNotes()
    {
        if (_notes.Count == 0) return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Body}"));
    }

    [Description("Clear all saved research notes")]
    public string ClearNotes()
    {
        _notes.Clear();
        return "All notes cleared.";
    }
}

